// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette{value: 10 ether}(); }

    function testFuzz_property(uint256 warpTime) public {
        warpTime = bound(warpTime, 1, type(uint48).max / 2);
        vm.warp(warpTime);

        address actor = address(0xA11CE);
        vm.deal(actor, 10 ether);
        vm.prank(actor);
        (bool ok,) = address(c).call{value: 10 ether}("");
        assertTrue(ok);

        // General rule: any successful call records the timestamp of its block (+1)
        assertTrue(c.pastBlockTime() == block.timestamp + 1);
    }
}
